import AVFoundation

/// Where a filmstrip's pictures come from (spec §11 GR-21): the plain asset,
/// or — for a media whose Camera Log converts, a PQ file with a peak (spec
/// §11 HD-12), or a video track labelled HLG or PQ — a one-clip composition
/// around it, through `CompositionBuilder` and step 0, so the strip is the
/// preview's picture. A still labelled HLG or PQ, or a PQ still with a peak,
/// draws its one tile the same way (`stillReader`, spec §11 HD-21).
/// The strip's marker says which: the flat `CacheStamp` for a plain strip,
/// exactly as before, and a `ConvertedThumbsStamp` for a converted one, which
/// records `fullRange` for an S-Log3 or V-Log media from a full-range source
/// (spec §11 GR-23), so a strip certified without it is drawn again.
///
/// Await-free (spec §11 W-8): the track's labels are read by key, as
/// `CompositionBuilder.convertsSources` reads them, and the awaiting stays in
/// `MediaImporter.thumbnails`, which asks `thumbnailReader` for its generator.

/// An HDR transfer step 0 converts and the plain generator does not draw as
/// step 0 does (GR-21's H0: HLG and PQ). SDR wide gamut is not one.
enum HDRTransfer: String, Codable, Equatable {
    case hlg, pq
}

/// What a strip is drawn through: a media's converting Camera Log (and its
/// LUT's file) or a PQ file's peak, or an HDR track's transfer.
struct ThumbnailInput: Equatable {
    /// The media's converting Camera Log or PQ peak; nil for an HDR input.
    let color: MediaColor?
    /// `urls[color.lut]` when `color.lut` is set; nil when it does not resolve.
    let lutURL: URL?
    /// Non-nil only when `color` is nil.
    let transfer: HDRTransfer?

    /// Camera Log or a PQ peak: nil unless the media is a video with a
    /// picture whose `color` step 0 converts, or a PQ still with a peak
    /// (`convertingColor(of:)`).
    init?(media: MediaSnapshot, urls: [UInt32: URL]) {
        guard let color = Self.convertingColor(of: media) else { return nil }
        self.color = color
        lutURL = color.lut.flatMap { urls[$0] }
        transfer = nil
    }

    /// HLG or PQ: the first of the track's format descriptions for which
    /// `InputConversion.choose(for:)` answers `.hlg` or `.pq`; nil for every
    /// other answer, `.sdrWide` and `.srgb` included.
    init?(track: AVAssetTrack) {
        let descriptions =
            CompositionBuilder.keyed(track, "formatDescriptions") as? [CMFormatDescription] ?? []
        var found: HDRTransfer?
        for description in descriptions where found == nil {
            switch InputConversion.choose(for: description) {
            case .hlg: found = .hlg
            case .pq: found = .pq
            default: continue
            }
        }
        guard let found else { return nil }
        color = nil
        lutURL = nil
        transfer = found
    }

    /// HLG or PQ by the still's own label (spec §11 HD-21):
    /// `StillColor.conversion(at:)`, a header read with no decode, answers
    /// `.hlg` or `.pq`; nil for every other still, which keeps today's tile.
    init?(still url: URL) {
        switch StillColor.conversion(at: url) {
        case .hlg?: transfer = .hlg
        case .pq?: transfer = .pq
        default: return nil  // an SDR still keeps today's tile
        }
        color = nil
        lutURL = nil
    }

    /// Whether the strip's picture follows the source's range: S-Log3 and
    /// V-Log, whose code domain does (`InputConversions.codeDomain`); not
    /// Apple Log, a LUT or an HDR transfer.
    var readsRange: Bool {
        switch color?.log {
        case .slog3, .vlog: return true
        default: return false
        }
    }

    /// The media's `color` when step 0 converts by it — a Camera Log
    /// (`InputConversion.choose(input:)`), or a PQ file's effective peak
    /// (spec §11 HD-12), so a change of either redraws the strip — else nil;
    /// without URLs, so the document's observer and the cache ledger key on
    /// it. A PQ file with no peak keeps the HDR transfer's strip. A still
    /// answers only for a PQ peak (spec §11 HD-21), so a set, clear, undo or
    /// redo of it starts a pass.
    static func convertingColor(of media: MediaSnapshot) -> MediaColor? {
        if media.kind == .image, media.hasVideo, let color = media.color {
            return color.pq?.effectivePeak != nil ? color : nil  // HD-21
        }
        guard media.kind == .video, media.hasVideo, let color = media.color,
            InputConversion.choose(input: color) != nil || color.pq?.effectivePeak != nil
        else { return nil }
        return color
    }
}

/// The marker of a strip drawn through step 0: the source's own
/// `CacheStamp`, and what converted it — the curve and gamut, or the LUT
/// named by its resolved path, size and modification second (so another
/// file of the same size and second is not taken for it), or the HDR
/// transfer; `fullRange` true for a `readsRange` input from a source
/// flagged full range (spec §11 GR-23); and `peak`, a PQ file's effective
---IC
        case .sGamut3: self = .sGamut3
        case .vGamut: self = .vGamut
        case .appleWideGamut: self = .appleWideGamut
        case .cinemaGamut: self = .cinemaGamut
        }
    }
}

/// Step 0's conversion of one source (spec §11 GR-15), chosen from its
/// buffer's colour labels: HLG or PQ to SDR Rec. 709, a wide-gamut SDR
/// source's matrix to BT.709, or an sRGB-transfer source's sRGB arm. nil —
/// the identity — for every other source, which is then sampled exactly as
/// before T3-1 (no pass, its own texture). A media's Camera Log (GR-16)
/// chooses before the labels: a maker's log curve and its camera gamut, or a
/// `lut` media's table. In an HLG project (spec §11 HD-2, HD-13) every arm
/// writes HLG-encoded BT.2020 instead, a BT.709 or untagged source takes
/// `.sdr` (HD-3's lift) and an HLG BT.2020 source is the identity.
enum InputConversion: Equatable {
    case hlg(InputPrimaries), pq(InputPrimaries), sdrWide(InputPrimaries), srgb(InputPrimaries)
    case log(LogCurve, InputPrimaries), lut(UInt32)
    /// A BT.709 or untagged source lifted into an HLG project by HD-3's lift
    /// (`InputConversions.liftSDR` is its CPU twin); chosen only in an HLG
    /// project, and the conversion every layer Frame Job draws is lifted by
    /// at upload (`LayerLift`).
    case sdr

    /// Whether a source answering this makes its composition a converting
    /// one (`ConvertingCompositor`, GR-15 as amended). False only for
    /// `.srgb(.bt709)`: that arm runs inside a converting composition, so the
    /// clip renders there as it does alone, but never makes one.
    var startsConversion: Bool { self != .srgb(.bt709) }

    /// GR-15's selector, by TRANSFER first: a log transfer (Apple Log's
    /// `LogTransferFunction`, which carries BT.2020 primaries and an
    /// unspecified transfer) stays the identity until GR-16 assigns it a
    /// conversion; HLG and PQ convert whatever their primaries (absent or
    /// unknown read as BT.2020); the sRGB transfer takes the sRGB arm with
    /// its primaries (absent or other read as BT.709); the BT.709 and BT.2020
    /// transfers convert only with BT.2020 or P3 D65 primaries. Anything else
    /// is the identity.
    static func choose(
        transfer: String?, primaries: String?, logTransfer: String?
    ) -> InputConversion? {
        guard logTransfer == nil else { return nil }
        switch transfer {
        case Label.hlg: return .hlg(hdrPrimaries(primaries))
        case Label.pq: return .pq(hdrPrimaries(primaries))
        case Label.sRGB: return srgb(primaries)
        case Label.bt709, Label.bt2020: return wide(primaries)
        default: return nil
        }
    }

    /// GR-16's selector, over a media's Camera Log as a recipe layer's
    /// `input` carries it: its curve and gamut (the curve's first when none
    /// is stored), else its LUT; nil for neither.
    static func choose(input: MediaColor) -> InputConversion? {
        if let log = input.log, let gamut = input.effectiveGamut {
            return .log(log, InputPrimaries(gamut))
        }
        return input.lut.map { .lut($0) }
    }

    /// Step 0's choice for one frame in a project of `output` (spec §11 HD-2):
    /// the media's Camera Log, else the frame's labels — exactly today's
    /// choice in an SDR project. In an HLG project an HLG BT.2020 source is
    /// already the working space (nil) and a source no arm converts — BT.709
    /// or untagged — is lifted (`.sdr`).
    static func choose(
        input: MediaColor?, buffer: CVPixelBuffer, output: CanvasOutput
    ) -> InputConversion? {
        let chosen = input.flatMap(choose(input:)) ?? choose(for: buffer)
        guard output == .hlg else { return chosen }
        switch chosen {
        case .hlg(.bt2020): return nil
        case nil: return .sdr
        default: return chosen
        }
    }

    /// The selector over a decoded frame's own attachments — the labels
    /// AVFoundation hands a compositor that conforms colour itself.
    static func choose(for buffer: CVPixelBuffer) -> InputConversion? {
        func label(_ key: CFString) -> String? {
            CVBufferCopyAttachment(buffer, key, nil) as? String
        }
        return choose(
            transfer: label(kCVImageBufferTransferFunctionKey),
            primaries: label(kCVImageBufferColorPrimariesKey),
            logTransfer: label(kCVImageBufferLogTransferFunctionKey))
    }

    /// The selector over a track's format description: the same three labels,
    /// as its extensions (`CompositionBuilder.convertsSources`).
    static func choose(for description: CMFormatDescription) -> InputConversion? {
        func label(_ key: CFString) -> String? {
            CMFormatDescriptionGetExtension(description, extensionKey: key) as? String
        }
        return choose(
            transfer: label(kCMFormatDescriptionExtension_TransferFunction),
            primaries: label(kCMFormatDescriptionExtension_ColorPrimaries),
            logTransfer: label(kCMFormatDescriptionExtension_LogTransferFunction))
    }

    /// The attachment values the selector reads, as strings.
    private enum Label {
        static let hlg = REDACTED as String
        static let pq = REDACTED as String
        static let bt709 = REDACTED as String
        static let bt2020 = kCVImageBufferTransferFunction_ITU_R_2020 as String
        static let sRGB = kCVImageBufferTransferFunction_sRGB as String
        static let primaries709 = kCVImageBufferColorPrimaries_ITU_R_709_2 as String
        static let primaries2020 = kCVImageBufferColorPrimaries_ITU_R_2020 as String
        static let p3D65 = kCVImageBufferColorPrimaries_P3_D65 as String
    }

    private static func hdrPrimaries(_ primaries: String?) -> InputPrimaries {
        switch primaries {
        case Label.p3D65: return .p3D65
        case Label.primaries709: return .bt709
        default: return .bt2020
        }
    }

    private static func srgb(_ primaries: String?) -> InputConversion? {
        switch primaries {
        case Label.primaries2020: return .srgb(.bt2020)
        case Label.p3D65: return .srgb(.p3D65)
        default: return .srgb(.bt709)
        }
    }

    private static func wide(_ primaries: String?) -> InputConversion? {
        switch primaries {
        case Label.primaries2020: return .sdrWide(.bt2020)
        case Label.p3D65: return .sdrWide(.p3D65)

    /// BT.2100 HLG, whatever the caller's format); otherwise, when the
    /// caller's format `keepsDepth`, PR-9's still (`DeepStillFrame.shows`) or
    /// PR-12's track (`shows`), asked in that order.
    static func reads(
        _ project: ReelProject, _ built: BuiltComposition, urls: [UInt32: URL], at t: Ticks,
        options: RecipeOptions, keepsDepth: Bool
    ) -> Bool {
        project.plan?.output == .hlg
            || (keepsDepth
                && (DeepStillFrame.shows(project, urls: urls, at: t, options: options)
                    || shows(project, built, at: t, options: options)))
    }

    /// True when the recipe at `max(0, t)` (with `options`) has a `track`
    /// layer whose composition track's segment at that time reads a file
    /// whose first video description `isDeep`.
    static func shows(
        _ project: ReelProject, _ built: BuiltComposition, at t: Ticks, options: RecipeOptions
    ) -> Bool {
        guard let recipe = project.recipe(at: max(0, t), options: options) else { return false }
        let time = CompositionBuilder.time(max(0, t))
        for layer in recipe.layers {
            guard case .track(let id) = layer.source,
                let track = built.composition.track(withTrackID: CMPersistentTrackID(id))
            else { continue }
            if let shown = description(of: track, at: time), isDeep(shown) { return true }
        }
        return false
    }

    /// The first video description of the file `track`'s segment at `time`
    /// reads: nil for an empty segment, one whose target range does not hold
    /// the time, or one with no file.
    private static func description(
        of track: AVCompositionTrack, at time: CMTime
    ) -> CMFormatDescription? {
        guard let segment = track.segment(forTrackTime: time), !segment.isEmpty,
            segment.timeMapping.target.containsTime(time), let url = segment.sourceURL,
            let source = CompositionBuilder.firstTrack(of: AVURLAsset(url: url), mediaType: .video)
        else { return nil }
        return (CompositionBuilder.keyed(source, "formatDescriptions") as? [CMFormatDescription])?
            .first
    }

    /// A VP9 description whose `vpcC` record (the VP codec ISOBMFF binding,
    /// version 1: version, three flag bytes, profile, level, then bitDepth:4 |
    /// chromaSubsampling:3 | videoFullRangeFlag:1 — GR-23's layout) says more
    /// than 8 bits. Every VP9 MP4 carries the record, and so does the
    /// built-in rewrap's copy of a WebM (`container_codec.rs`'s `vpcc()`).
    /// Anything else — another codec, no record, one shorter than 7 bytes or
    /// of another version — is not deep.
    static func isDeep(_ description: CMFormatDescription) -> Bool {
        guard CMFormatDescriptionGetMediaSubType(description) == kCMVideoCodecType_VP9,
            let atoms = CMFormatDescriptionGetExtension(
                description,
                extensionKey: kCMFormatDescriptionExtension_SampleDescriptionExtensionAtoms)
                as? [String: Any],
            let record = atoms["vpcC"] as? Data, record.count >= 7,
            record[record.startIndex] == 1
        else { return false }
        return record[record.startIndex + 6] >> 4 > 8
    }
}
